#!/usr/bin/env node
/**
 * Install pre-commit hook vào .git/hooks/pre-commit.
 * Hook sẽ chạy `node scripts/pre-commit-qc.js` trước mỗi commit.
 *
 * Usage: `npm run qc:install-hook`
 */

const fs = require("fs");
const path = require("path");

const HOOK_CONTENT = `#!/usr/bin/env node
// Auto-generated by scripts/qc-install-hook.js
// Chạy QC trước mỗi commit. Bỏ qua bằng: git commit --no-verify
const { spawnSync } = require("child_process");
const path = require("path");
const projectRoot = path.resolve(__dirname, "..", "..");
const result = spawnSync("node", [path.join(projectRoot, "scripts", "pre-commit-qc.js")], {
  stdio: "inherit",
});
process.exit(result.status || 0);
`;

const hookPath = path.join(__dirname, "..", ".git", "hooks", "pre-commit");
fs.writeFileSync(hookPath, HOOK_CONTENT, { mode: 0o755 });
console.log(`✓ Pre-commit hook installed: ${hookPath}`);
console.log(`  Bỏ qua QC khi commit: git commit --no-verify`);
